test-case.test:
declare %updating function local:safe-rename(
  $node as element(),
  $name as xs:string
) {
  try { rename node $node as $name }
  catch err:XQDY0074 { () }
};
<a><b/><c/></a> transform with {
  local:safe-rename(b, 'x'),
  local:safe-rename(c, '1')
}

let $a := <a/>
return try { delete node $a }
  catch * { () }

declare %updating function local:fail(
  $node as element()
) {
  insert node <b/> into $node,
  error()
};
<a/> transform with {
  try { local:fail(.) }
  catch * { insert node <c/> into . }
}

let $x := <x/>
return <a/> transform with {
  try { insert node <b/> into $x, error() }
  catch * { insert node <c/> into . }
}

let $a := <a/>
let $x := try { delete node $a } catch * { () }
return $x

let $x := <x/>
return <a/> transform with {
  try { insert node <b/> into $x }
  catch * { () }
}
